// project initialization
let backgroundList = [assets.image`springBackground`, assets.image`summerBackground`, assets.image`autumnBackground`]
let seasonList = ["spring", "summer", "autumn", "winter"]
let backgroundIndex = 0

tiles.setCurrentTilemap(assets.tilemap`level`)

scene.setBackgroundImage(backgroundList[backgroundIndex])
scroller.setBackgroundScrollOffset(80, 0)

let mySprite = sprites.create(assets.image`myImage`, SpriteKind.Player)
scene.cameraFollowSprite(mySprite)
tiles.placeOnTile(mySprite, tiles.getTileLocation(4, 6))

// project events
game.onUpdate(function () {
    mySprite.sayText(seasonList[backgroundIndex])
    if (controller.right.isPressed() && scroller.getBackgroundXOffset() < 1) {
        if (backgroundIndex == 3) {
            backgroundIndex = 0
        } else {
            backgroundIndex++
        }
        scroller.setBackgroundScrollOffset(159, 0)
    } else if (controller.left.isPressed() && scroller.getBackgroundXOffset() > 159) {
        if (backgroundIndex == 0) {
            backgroundIndex = 3
        } else {
            backgroundIndex--
        }
    }
    scene.setBackgroundImage(backgroundList[backgroundIndex])
})

controller.right.onEvent(ControllerButtonEvent.Pressed, function () {
    scroller.scrollBackgroundWithSpeed(-30, 0)
    animation.runImageAnimation(mySprite, assets.animation`catRight`, 100, true)
})

controller.left.onEvent(ControllerButtonEvent.Pressed, function () {
    scroller.scrollBackgroundWithSpeed(30, 0)
    animation.runImageAnimation(mySprite, assets.animation`catLeft`, 100, true)
})

controller.right.onEvent(ControllerButtonEvent.Released, function () {
    scroller.scrollBackgroundWithSpeed(-30, 0)
    animation.stopAnimation(animation.AnimationTypes.MovementAnimation, mySprite)
})

controller.left.onEvent(ControllerButtonEvent.Released, function () {
    scroller.scrollBackgroundWithSpeed(30, 0)
    animation.stopAnimation(animation.AnimationTypes.MovementAnimation, mySprite)
})

